# ---------------------------------------------------------------------------
# File: users.py
# The "users" modular component: a Flask Blueprint containing all user-
# related routes. It knows nothing about the main application other than
# that it will be mounted somewhere by the caller.
# ---------------------------------------------------------------------------
from flask import Blueprint, jsonify, request

users_bp = Blueprint("users", __name__)

_USERS = {
    1: {"id": 1, "name": "Alice"},
    2: {"id": 2, "name": "Bob"},
}
_NEXT_ID = 3


@users_bp.get("/")
def list_users():
    return jsonify(list(_USERS.values()))


@users_bp.get("/<int:user_id>")
def get_user(user_id):
    user = _USERS.get(user_id)
    if user is None:
        return jsonify({"error": "user not found"}), 404
    return jsonify(user)


@users_bp.post("/")
def create_user():
    global _NEXT_ID
    payload = request.get_json(silent=True) or {}
    name = payload.get("name")
    if not name:
        return jsonify({"error": "'name' is required"}), 400

    user = {"id": _NEXT_ID, "name": name}
    _USERS[_NEXT_ID] = user
    _NEXT_ID += 1
    return jsonify(user), 201


@users_bp.delete("/<int:user_id>")
def delete_user(user_id):
    if user_id not in _USERS:
        return jsonify({"error": "user not found"}), 404
    del _USERS[user_id]
    return "", 204


# ---------------------------------------------------------------------------
# File: app.py
# Main application: creates the Flask app and attaches the "users"
# component under the "/users" URL prefix.
# ---------------------------------------------------------------------------
from flask import Flask

from users import users_bp


def create_app():
    app = Flask(__name__)
    app.register_blueprint(users_bp, url_prefix="/users")

    @app.get("/")
    def index():
        return {"message": "Welcome to the LCP demo API"}

    return app


app = create_app()

if __name__ == "__main__":
    app.run(debug=True)

